class BalancedBrackets:
    LEFT_BRACKETS = ("(", "{", "[")
    RIGHT_BRACKETS = (")", "}", "]")
    BRACKET_PAIRS = {")": "(", "}": "{", "]": "["}

    def __init__(self, expr):
        self._stack = []
        self._left_brackets = list(self.LEFT_BRACKETS)
        self._right_brackets = list(self.RIGHT_BRACKETS)
        self._expr = expr

    @property
    def expr(self):
        return self._expr

    @expr.setter
    def expr(self, value):
        self._expr = value

    @property
    def stack(self):
        return self._stack

    def clear_expr(self):
        self.expr = ''.join(c for c in self.expr if (c in self.left_brackets or c in self.right_brackets))

    def _process_bracket(self, bracket):
        if bracket in self.left_brackets:
            self.stack.append(bracket)
        else:
            self._validate_bracket_match(bracket)

    def _validate_bracket_match(self, closing_bracket):
        if not self.stack:
            raise ValueError("Unmatched closing bracket found")
        current_brkt = self.stack.pop()
        expected_opening = self.BRACKET_PAIRS[closing_bracket]
        if current_brkt != expected_opening:
            return False
        return True

    @property
    def left_brackets(self):
        return self._left_brackets

    @left_brackets.setter
    def left_brackets(self, value):
        self._left_brackets = value

    @property
    def right_brackets(self):
        return self._right_brackets

    @right_brackets.setter
    def right_brackets(self, value):
        self._right_brackets = value

    def check_balanced_brackets(self):
        self.clear_expr()
        for Brkt in self.expr:
            self._process_bracket(Brkt)
        return not self.stack
